import { Link } from "react-router-dom"
const DUMMY = [
    {
        id:1,
        title: 'event1'
    },
    {
        id:2,
        title: 'event2'
    },
    {
        id:3,
        title: 'event3'
    },
]

export default function EventPage(){
    return(
        <>
            <h1>Event page</h1>
            <ul>
                {DUMMY.map((event) =>(
                    <li key={event.id}>
                        <Link to={event.id.toString()}>{event.title}</Link>
                    </li>
                ))}
            </ul>
        </>
        
    )
}
